//! Explicit opt-in differential tests. Product code never invokes Node.
use fugue::{git::Git,journal,view::View};
use serde_json::{json,Value};
use std::{path::Path,process::Command};
fn node(script:&str,args:&[&Path])->Value{let mut c=Command::new("node");c.args(["--input-type=module","--eval",script]);for p in args{c.arg(p);}let q=c.output().expect("Node 24 is required for this explicit oracle test");assert!(q.status.success(),"{}",String::from_utf8_lossy(&q.stderr));serde_json::from_slice(&q.stdout).unwrap()}
fn upstream()->std::path::PathBuf{Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf()}
fn repo()->tempfile::TempDir{let d=tempfile::tempdir().unwrap();assert!(Command::new("git").args(["init","-q","--initial-branch=main"]).arg(d.path()).status().unwrap().success());d}
#[test]#[ignore="explicit upstream Node 24 differential oracle"]
fn canonical_crc_interoperates_with_node_for_numbers_and_utf16_keys(){let d=tempfile::tempdir().unwrap();let up=upstream();let v=node(r#"const root=process.argv[1],up=process.argv[2];const fs=await import('node:fs/promises');const {encodeEvent}=await import(up+'/src/log/envelope.ts');const event={t:'signal',agent:'round',fraction:0.000001,tiny:1e-7,large:1e21,negativeZero:-0,nested:{'😀':2,'\ue000':1},text:'α\n\t𝄞'};await fs.mkdir(root+'/.fugue/log',{recursive:true});await fs.writeFile(root+'/.fugue/log/round.jsonl',encodeEvent(1,'round',event)+'\n');console.log(JSON.stringify(event));"#,&[d.path(),&up]);assert_eq!(journal::read(d.path(),"round").unwrap()[0].event,v);let event=json!({"t":"signal","agent":"round","fraction":0.000001,"tiny":1e-7,"large":1e21,"nested":{"😀":2,"\u{e000}":1},"text":"α\n\t𝄞"});journal::append(d.path(),"round",event.clone()).unwrap();let got=node(r#"const root=process.argv[1],up=process.argv[2];const fs=await import('node:fs/promises');const {decodeLine}=await import(up+'/src/log/envelope.ts');const lines=(await fs.readFile(root+'/.fugue/log/round.jsonl','utf8')).trim().split('\n');const v=lines.map(decodeLine);if(v.some(x=>!x.ok))throw new Error(JSON.stringify(v));console.log(JSON.stringify(v[1].event));"#,&[d.path(),&up]);assert_eq!(got,event);}
#[test]#[ignore="explicit upstream Node 24 differential oracle"]
fn operation_sequence_and_checkpoint_tree_match_node(){let rust=repo();let oracle=repo();let up=upstream();let mut v=View::load(rust.path(),"round",None).unwrap();v.write("dir/a",b"one\0two",None).unwrap();v.write("dir/b",b"two",Some(0o755)).unwrap();v.symlink("link","dir/a").unwrap();v.rename("dir/a","renamed").unwrap();v.chmod("dir/b",0o644).unwrap();v.remove("link").unwrap();v.write("dir/new",b"new",None).unwrap();v.checkpoint("sequence").unwrap();v=View::load(rust.path(),"round",None).unwrap();v.rename("renamed","again").unwrap();v.chmod("dir/new",0o755).unwrap();let c=v.checkpoint("second").unwrap();let q=node(r#"const root=process.argv[1],up=process.argv[2];const {openTruth}=await import(up+'/src/truth/truth.ts');const {openLog}=await import(up+'/src/log/log.ts');const {lowerFor}=await import(up+'/src/view/lower.ts');const {loadView}=await import(up+'/src/view/view.ts');const {applyEdit}=await import(up+'/src/view/edit.ts');const {checkpoint}=await import(up+'/src/checkpoint.ts');const {snapshotOf}=await import(up+'/src/view/snapshot.ts');const truth=openTruth(root),log=openLog(root,{write:'round',sync:'each'}),view=await loadView(log,'round',{lower:await lowerFor(truth,'round')});const target={truth,log,view,writer:'round'};for(const d of [{kind:'add',path:'dir/a',bytes:Buffer.from('one\0two'),mode:0o100644},{kind:'add',path:'dir/b',bytes:Buffer.from('two'),mode:0o100755},{kind:'symlink',path:'link',target:'dir/a'},{kind:'rename',from:'dir/a',to:'renamed'},{kind:'chmod',path:'dir/b',mode:0o644},{kind:'delete',path:'link'},{kind:'add',path:'dir/new',bytes:Buffer.from('new'),mode:0o100644}])await applyEdit(target,d);let c=await checkpoint({truth,log,writer:'round',entries:await snapshotOf(view),rev:view.rev,msg:'sequence',expectedOld:view.base});const next=await loadView(log,'round',{lower:await lowerFor(truth,'round')});const nt={truth,log,view:next,writer:'round'};await applyEdit(nt,{kind:'rename',from:'renamed',to:'again'});await applyEdit(nt,{kind:'chmod',path:'dir/new',mode:0o755});c=await checkpoint({truth,log,writer:'round',entries:await snapshotOf(next),rev:next.rev,msg:'second',expectedOld:next.base});const clean=await loadView(log,'round',{lower:await lowerFor(truth,'round')});const dif=clean.diff().map(x=>x.kind==='add'||x.kind==='modify'?{kind:x.kind,path:x.path,mode:x.mode,size:x.bytes.length}:x);console.log(JSON.stringify({tree:c.tree,rev:clean.rev,revs:clean.revs,list:await clean.list(''),diff:dif}));await log.close();await truth.close();"#,&[oracle.path(),&up]);assert_eq!(c["tree"],q["tree"]);let reloaded=View::load(rust.path(),"round",None).unwrap();assert_eq!(reloaded.rev,q["rev"].as_u64().unwrap());assert_eq!(json!(reloaded.revs),q["revs"]);assert_eq!(reloaded.list("").unwrap(),q["list"]);assert_eq!(reloaded.diff(0).unwrap(),q["diff"]);let g=Git::open(rust.path()).unwrap();let tree=g.tree(c["tree"].as_str().unwrap()).unwrap();let og=Git::open(oracle.path()).unwrap();assert_eq!(tree,og.tree(q["tree"].as_str().unwrap()).unwrap());}

#[test]#[ignore="explicit upstream Node 24 differential oracle"]
fn mixed_writer_merged_order_matches_node(){let d=tempfile::tempdir().unwrap();let up=upstream();journal::append(d.path(),"round",json!({"t":"signal","id":"r1"})).unwrap();journal::append(d.path(),"agent/r/2",json!({"t":"signal","id":"a2"})).unwrap();journal::append(d.path(),"agent/r/1",json!({"t":"signal","id":"a1"})).unwrap();journal::append(d.path(),"round",json!({"t":"signal","id":"r2"})).unwrap();journal::append(d.path(),"😀",json!({"t":"signal","id":"astral"})).unwrap();journal::append(d.path(),"\u{e000}",json!({"t":"signal","id":"bmp"})).unwrap();let got=node(r#"const root=process.argv[1],up=process.argv[2];const {openLog}=await import(up+'/src/log/log.ts');const log=openLog(root);const rows=[];for await(const x of log.readMerged())rows.push({seq:x.pos.seq,writer:x.pos.writer,event:x.e});await log.close();console.log(JSON.stringify(rows));"#,&[d.path(),&up]);assert_eq!(serde_json::to_value(journal::merged(d.path()).unwrap()).unwrap(),got);}

#[test]#[ignore="explicit upstream Node 24 differential oracle"]
fn legacy_nested_writer_locks_exclude_both_runtimes(){use std::io::{BufRead,BufReader};use std::process::Stdio;struct Child(std::process::Child);impl Drop for Child{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}let d=tempfile::tempdir().unwrap();let up=upstream();let mut c=Child(Command::new("node").args(["--input-type=module","--eval",r#"const root=process.argv[1],up=process.argv[2];const {holdWriter}=await import(up+'/src/log/hold.ts');const h=holdWriter(root,'agent/r1/1');console.log('ready');setInterval(()=>{},1000);"#]).arg(d.path()).arg(&up).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap());let mut line=String::new();BufReader::new(c.0.stdout.take().unwrap()).read_line(&mut line).unwrap();assert_eq!(line.trim(),"ready");assert!(journal::Lock::take(d.path(),"agent/r1/1").is_err());assert!(!d.path().join(".fugue/log/agent/r1/1.lock").exists());c.0.kill().unwrap();c.0.wait().unwrap();let l=journal::Lock::take(d.path(),"agent/r1/1").unwrap();let got=node(r#"const root=process.argv[1],up=process.argv[2];const {holdWriter}=await import(up+'/src/log/hold.ts');let held=false;try{const h=holdWriter(root,'agent/r1/1');h.release();}catch(e){if(e.name!=='LogHeldError')throw e;held=true;}console.log(JSON.stringify({held}));"#,&[d.path(),&up]);assert_eq!(got,json!({"held":true}));drop(l);assert!(!d.path().join(".fugue/log/agent/r1/1.lock").exists());assert!(!d.path().join(".fugue/log/agent/r1/agent/r1/1.lock").exists());}

#[test]#[ignore="explicit upstream Node 24 differential oracle"]
fn explicit_empty_git_directories_match_node_lists_and_tombstones() {
    let d=repo(); let up=upstream(); let g=Git::open(d.path()).unwrap();
    let empty=g.put_tree(&std::collections::BTreeMap::new()).unwrap();
    let tree=String::from_utf8(g.run(&["mktree","-z"],Some(format!("040000 tree {empty}\tempty\0").as_bytes())).unwrap()).unwrap().trim().to_owned();
    let commit=g.commit_tree(&tree,&[],"empty directory").unwrap(); g.advance("refs/heads/main",&commit,None).unwrap();
    let mut v=View::load(d.path(),"round",None).unwrap();
    let script=r#"const root=process.argv[1],up=process.argv[2];const {openTruth}=await import(up+'/src/truth/truth.ts');const {openLog}=await import(up+'/src/log/log.ts');const {lowerFor}=await import(up+'/src/view/lower.ts');const {loadView}=await import(up+'/src/view/view.ts');const truth=openTruth(root),log=openLog(root);const view=await loadView(log,'round',{lower:await lowerFor(truth,'round')});console.log(JSON.stringify({list:await view.list(''),empty:await view.list('empty'),stat:await view.stat('empty')}));await log.close();await truth.close();"#;
    let q=node(script,&[d.path(),&up]); assert_eq!(v.list("").unwrap(),q["list"]); assert_eq!(v.list("empty").unwrap(),q["empty"]); assert_eq!(v.stat("empty").unwrap(),q["stat"]);
    v.remove("empty").unwrap(); let q=node(script,&[d.path(),&up]); assert_eq!(v.list("").unwrap(),q["list"]); assert_eq!(v.stat("empty").unwrap(),q["stat"]);
}
